const lv_image_dsc_t *arrow_for_turn(int trn)
{
    switch (trn) {
    case 1:
        return &arrow_straight;
    case 2:
        return &arrow_left;
    case 3:
        return &arrow_right;
    case 4:
    case 13:
    case 15:
        return &arrow_slight_left;
    case 5:
    case 14:
    case 16:
        return &arrow_slight_right;
    case 6:
        return &arrow_sharp_left;
    case 7:
        return &arrow_sharp_right;
    case 8:
    case 9:
        return &arrow_uturn;
    case 10:
    case 11:
    case 12:
    case 19:
    case 20:
        return &arrow_roundabout;
    case 17:
        return &arrow_arrive;
    default:
        return NULL;
    }
}

const lv_image_dsc_t *weather_icon(int cond)
{
    switch (cond) {
    case 0:
        return &wx_clear;
    case 1:
        return &wx_partly;
    case 2:
        return &wx_cloudy;
    case 3:
        return &wx_rain;
    case 4:
        return &wx_storm;
    case 5:
        return &wx_fog;
    default:
        return NULL;
    }
}

